// src/components/Input.jsx
import React from 'react';

const Input = ({ label, ...props }) => {
  return (
    <div>
      {label && <label className="block text-sm font-medium text-darkText mb-1">{label}</label>}
      <input
        {...props}
        className="w-full p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200 outline-none"
      />
    </div>
  );
};

export default Input;
